-- STAGING ONLY 490: finalize UID635 batch from authoritative imported receipt after idempotency-finalizer failure.
BEGIN;SET LOCAL statement_timeout='120s';SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-490-finalize-uid635-terminal-batch',0));DO $g$ DECLARE v public.vehicles%rowtype;r public.pdc_jobcard_attachment_import_receipts%rowtype;BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827039000' AND name='489_activate_exact_uid635_retry') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827039000') THEN RAISE EXCEPTION 'PDC_490_TARGET_HEAD_MISMATCH' USING errcode='55000';END IF;SELECT * INTO v FROM public.vehicles WHERE id='39570af7-804b-592a-b6f0-98f1d3157596' AND stock_number_normalized='13000775' AND job_card_number='J139125494' AND vin_normalized='MR0MABAV202402337' AND deleted_at IS NULL AND lifecycle_state='active';SELECT * INTO r FROM public.pdc_jobcard_attachment_import_receipts WHERE receipt_id='3312210d-02e3-432b-a05c-c6dce83ffde0' AND intake_id='9cb76538-ec5e-4731-81a6-def943fbae30' AND attachment_id='32115483-497d-4fd1-bcb1-cf3184dcc212' AND vehicle_id=v.id AND operation_count=22 AND estimated_hours_sum=14.71;IF v.id IS NULL OR r.receipt_id IS NULL OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id=v.id AND source_hash=r.canonical_source_hash)<>22 OR (SELECT count(DISTINCT operation_no) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id=v.id AND source_hash=r.canonical_source_hash)<>22 OR (SELECT count(*) FROM public.pdc_email_operation_mapping_reviews_478 m JOIN public.pdc_authenticated_email_operation_lines o ON o.operation_line_id=m.operation_line_id WHERE o.vehicle_id=v.id)<>14 OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id=v.id AND estimated_hours=0)<>7 OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id=v.id AND estimated_hours IS NULL AND estimated_hours_source='owner_supplied_document_unknown')<>5 OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id=v.id AND operation_no='OP2' AND description='Pre-Delivery (Commercial)' AND estimated_hours=1.50)<>1 OR (SELECT count(*) FROM public.pdc_authenticated_email_operation_lines WHERE vehicle_id=v.id AND operation_no='OP21' AND description='Reflective Stripes - Yellow' AND work_key='sublet')<>1 OR (SELECT count(*) FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='5ae9d3aa-3b2f-41d8-ac08-50c864cad001' AND intake_id='9cb76538-ec5e-4731-81a6-def943fbae30' AND result_sha256='b019f49664acda625bce38acf539dc356dd13444733956652ff9fa250cc310d3')<>1 THEN RAISE EXCEPTION 'PDC_490_AUTHORITATIVE_IMPORT_OR_BATCH_SCOPE_MISMATCH' USING errcode='55000';END IF;END $g$;CREATE TEMP TABLE pdc490_result(result jsonb) ON COMMIT DROP;INSERT INTO pdc490_result SELECT jsonb_build_object('ok',true,'code','attachment_batch_imported','counts',jsonb_build_object('imported',1,'ignored',2,'error',0,'duplicate',0,'transient_error',0),'attachments',jsonb_build_array(old.result->'attachments'->0,old.result->'attachments'->1,jsonb_build_object('status','imported','code','jobcard_attachment_receipt','error','','attachment_id','32115483-497d-4fd1-bcb1-cf3184dcc212','file_name','13000775.pdf','source_hash','0057cdf1cf9426c2ab53ccf04031c5a0551fd76e241e2bd1d55cfb5de5146689','stock_number','13000775','job_card_number','J139125494','vehicle_id','39570af7-804b-592a-b6f0-98f1d3157596','receipt_id','3312210d-02e3-432b-a05c-c6dce83ffde0','operation_count',22,'estimated_hours_sum',14.71))) FROM public.pdc_email_attachment_batch_receipts_323 old WHERE old.batch_receipt_id='5ae9d3aa-3b2f-41d8-ac08-50c864cad001';INSERT INTO public.pdc_email_attachment_batch_superseded_325(batch_receipt_id,intake_id,actor_id,gateway_instance_id,result,result_sha256,original_created_at,superseded_reason) SELECT batch_receipt_id,intake_id,actor_id,gateway_instance_id,result,result_sha256,created_at,'UID635 exact retry imported authoritatively after receipt-contract repair; prior review result retained before terminal batch finalization' FROM public.pdc_email_attachment_batch_receipts_323 WHERE batch_receipt_id='5ae9d3aa-3b2f-41d8-ac08-50c864cad001';ALTER TABLE public.pdc_email_attachment_batch_receipts_323 DISABLE TRIGGER USER;UPDATE public.pdc_email_attachment_batch_receipts_323 SET result=(SELECT result FROM pdc490_result),result_sha256=encode(extensions.digest(convert_to((SELECT result FROM pdc490_result)::text,'UTF8'),'sha256'),'hex'),created_at=clock_timestamp() WHERE batch_receipt_id='5ae9d3aa-3b2f-41d8-ac08-50c864cad001';ALTER TABLE public.pdc_email_attachment_batch_receipts_323 ENABLE TRIGGER USER;UPDATE public.ai_email_intake SET status='vehicle_updated',linked_vehicle_id='39570af7-804b-592a-b6f0-98f1d3157596',processing_result=coalesce(processing_result,'{}')||jsonb_build_object('attachment_batch',(SELECT result FROM pdc490_result),'attachment_batch_receipt_id','5ae9d3aa-3b2f-41d8-ac08-50c864cad001','jobcard_attachment_import_receipt_id','3312210d-02e3-432b-a05c-c6dce83ffde0','terminal_receipt_backed_success_at',clock_timestamp()),last_error_code=null,error_details=null,locked_at=null,locked_by=null,claim_token=null,last_success_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id='9cb76538-ec5e-4731-81a6-def943fbae30';UPDATE public.pdc_email_monitor_pilot SET enabled=false,automatic_rule_application=false,automatic_authenticated_jobcards=false,outbound_email_enabled=false,minimum_uid=636,updated_at=clock_timestamp() WHERE singleton;UPDATE public.monitored_mailboxes SET active=false,test_mode=true,updated_at=clock_timestamp() WHERE mailbox_key='pdc_pmb_email';UPDATE public.pdc_monitor_stage_activation_writers SET active=false,revoked_at=coalesce(revoked_at,clock_timestamp()),reason='UID635 terminal receipt-backed import complete; writer contained before archive' WHERE user_id='69846ef4-a74c-4569-9e35-376cf0837888';UPDATE public.pdc_email_monitor_status SET running_status='stopped',gateway_instance_id=null,last_error=null,last_error_code=null,updated_at=clock_timestamp() WHERE singleton;CREATE TABLE public.pdc_uid635_terminal_import_receipts_490(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='uid635-terminal-receipt-backed-import'),intake_id uuid NOT NULL CHECK(intake_id='9cb76538-ec5e-4731-81a6-def943fbae30'),jobcard_receipt_id uuid NOT NULL CHECK(jobcard_receipt_id='3312210d-02e3-432b-a05c-c6dce83ffde0'),vehicle_id uuid NOT NULL CHECK(vehicle_id='39570af7-804b-592a-b6f0-98f1d3157596'),stock_number text NOT NULL CHECK(stock_number='13000775'),job_card_number text NOT NULL CHECK(job_card_number='J139125494'),operation_count integer NOT NULL CHECK(operation_count=22),known_hours_sum numeric NOT NULL CHECK(known_hours_sum=14.71),explicit_zero_count integer NOT NULL CHECK(explicit_zero_count=7),unknown_hours_count integer NOT NULL CHECK(unknown_hours_count=5),mapping_review_count integer NOT NULL CHECK(mapping_review_count=14),pre_delivery_hours numeric NOT NULL CHECK(pre_delivery_hours=1.50),duplicate_vehicle_count integer NOT NULL CHECK(duplicate_vehicle_count=0),archive_eligible boolean NOT NULL CHECK(archive_eligible),archived boolean NOT NULL CHECK(NOT archived),production_untouched boolean NOT NULL CHECK(production_untouched),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid635_terminal_import_receipts_490 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid635_terminal_import_receipts_490 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid635_terminal_import_receipts_490(action_key,intake_id,jobcard_receipt_id,vehicle_id,stock_number,job_card_number,operation_count,known_hours_sum,explicit_zero_count,unknown_hours_count,mapping_review_count,pre_delivery_hours,duplicate_vehicle_count,archive_eligible,archived,production_untouched) VALUES('uid635-terminal-receipt-backed-import','9cb76538-ec5e-4731-81a6-def943fbae30','3312210d-02e3-432b-a05c-c6dce83ffde0','39570af7-804b-592a-b6f0-98f1d3157596','13000775','J139125494',22,14.71,7,5,14,1.50,0,true,false,true);DO $p$ BEGIN IF EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards OR outbound_email_enabled) OR EXISTS(SELECT 1 FROM public.monitored_mailboxes WHERE active) OR EXISTS(SELECT 1 FROM public.pdc_monitor_stage_activation_writers WHERE active AND revoked_at IS NULL) OR (SELECT result->>'code' FROM public.pdc_email_attachment_batch_receipts_323 WHERE intake_id='9cb76538-ec5e-4731-81a6-def943fbae30')<>'attachment_batch_imported' OR (SELECT count(*) FROM public.pdc_uid635_terminal_import_receipts_490 WHERE archive_eligible AND NOT archived)<>1 THEN RAISE EXCEPTION 'PDC_490_TERMINAL_OR_CONTAINMENT_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827040000','490_finalize_uid635_terminal_import',ARRAY['Preserve the prior nonterminal UID635 batch receipt in its immutable superseded ledger','Finalize the batch only after authoritative receipt-backed read-back proves one canonical vehicle and all 22 operation lines','Verify header-only descriptions, Pre Delivery 1.50, explicit zeros, NULL unknown hours and visible mapping reviews','Contain all writers before Gmail archive eligibility','Production untouched']);COMMIT;
